function About(){return"<h1>About Us!</h1>"}function Contact(){return"<h1>Contact Us!</h1>"}function Home(){return"<h1>Welcome Home!</h1>"}function NotFound(){return"<h1>Not Found!</h1>"}function GoTo(e){var o=document.getElementById("root"),a="";switch(e){case"home":a=Home();break;case"about":a=About();break;case"contact":a=Contact();break;default:a=NotFound()}o.innerHTML=a}GoTo("home");